<script lang="ts" module>
	// Public feed state belongs to this mounted query, never a module cache.
</script>

<script lang="ts">
	import { page } from "$app/state";
	import { API, Constants } from "$lib";
	import { Button, buttonVariants } from "$lib/components/ui/button";
	import Carousel from "$lib/components/ui/Carousel.svelte";
	import ErrorComponent from "$lib/components/ErrorComponent.svelte";
	import { prefs } from "$lib/stores";
	import { ArrowRightIcon } from "@lucide/svelte";
	import { onMount } from "svelte";
	import { createPublicMangaWidgetRead } from "$platform/public-manga-widget-read";
	import MangaSearchEntryCard from "./MangaSearchEntryCard.svelte";
	import MangaSearchEntrySkeleton from "./MangaSearchEntrySkeleton.svelte";
	const widget = createPublicMangaWidgetRead(() => {
		const q = new URLSearchParams();
		prefs.applyMangaPreferences(q);
		q.set("sort", Constants.Manga.SortBy.CreatedAt); q.set("limit", "10");
		return q;
	}, async q => API.Manga.Search(q));
	const widgetState = widget.state;
	let feed = $derived($widgetState.feed), isMounted = $derived($widgetState.isMounted), isLoading = $derived($widgetState.isLoading), error = $derived($widgetState.error);
	let mountedLifecycle = $state(false);
	onMount(() => { mountedLifecycle = true; });
	$effect.pre(() => {
		const preferences = $prefs, route = page.url.href;
		if (mountedLifecycle) widget.synchronize();
	});
</script>

{#if !isMounted || feed?.data?.length || error}
	<section>
		<header class="mb-3 flex items-center gap-2">
			<div class="flex w-0 flex-auto items-center gap-2">
				<h2 class="text-xl font-medium">Recently Added Titles</h2>
			</div>
			<div class="flex shrink-0 items-center gap-2">
				<a class={buttonVariants({ variant: "ghost", size: "icon" })} href="/search?sort=createdAt">
					<ArrowRightIcon class="size-6" />
				</a>
			</div>
		</header>
		{#if error}
			<ErrorComponent {error} />
			<Button variant="outline" disabled={isLoading} onclick={widget.retry}>Retry titles</Button>
		{:else}
		<Carousel slidesPerView={2} breakpoints={Constants.MangaSliderBreakpoints} spaceBetween={12}>
			{#if isMounted && feed?.data?.length}
				{#each feed.data as manga (manga)}
					<article class="swiper-slide relative">
						<MangaSearchEntryCard {manga} isGrid />
					</article>
				{/each}
			{:else}
				<Carousel slidesPerView={2} breakpoints={Constants.MangaSliderBreakpoints} spaceBetween={12}>
					{#each Array.from({ length: 10 })}
						<article class="swiper-slide relative">
							<MangaSearchEntrySkeleton isGrid />
						</article>
					{/each}
				</Carousel>
			{/if}
		</Carousel>
		{/if}
	</section>
{/if}
